/// Phosphor SVG icons (256x256 viewBox, fill="currentColor")
/// Used across modern editor panels, activity rail, and tree views.

use gpui::{px, Styled, Svg};

pub fn render_icon(svg_data: &'static [u8], size_px: f32, color: gpui::Rgba) -> Svg {
    gpui::svg()
        .size(px(size_px))
        .text_color(color)
        .data(svg_data)
}

